{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Sound-guided gatherings for rest, intention, and gentle release in {{CITY}}, {{STATE}}. Cohort-based offerings and private sessions.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Work</a>
        <a href="/pricing.html">Plans & Rates</a>
        <a href="/about.html">Our Story</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="try-btn" id="try-now">Try it now</button>
    </div>
  </header>

  <main>
    <section class="hero reveal" data-reveal>
      <div class="wrap">
        <div class="hero-grid">
          <div class="hero-copy">
            <h1>Enter an hour that shapes down the day.</h1>
            <p class="lead">We guide small cohorts through layered sound and gentle pacing — a way to move from clamor into softness and clear the edges of a busy mind.</p>
            <div class="hero-ctas">
              <a class="btn primary" href="/events.html">Find the next circle</a>
              <button class="btn ghost" id="try-now-2">Quick practice</button>
            </div>
            <p class="tiny">Cohort sessions, private bookings, and seasonal intensives. Please review contraindications before booking.</p>
          </div>
          <div class="hero-art" aria-hidden="true">
            <svg class="orb" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
              <defs>
                <radialGradient id="g" cx="30%" cy="30%" r="70%">
                  <stop offset="0%" stop-color="#f7efe6"/>
                  <stop offset="100%" stop-color="#d8c4a6"/>
                </radialGradient>
              </defs>
              <circle cx="100" cy="100" r="90" fill="url(#g)"/>
              <path d="M20,150 C60,60 140,60 180,150" stroke="#cba57f" stroke-width="6" fill="none" stroke-linecap="round"/>
            </svg>
          </div>
        </div>
      </div>
    </section>

    <section class="social-proof reveal" data-reveal>
      <div class="wrap">
        <h2>Small circles. Big shifts.</h2>
        <div class="testimonials">
          <blockquote>
            "After two sessions I sleep calmer and notice my shoulders drop earlier in the evening."<cite>— A., local teacher</cite>
          </blockquote>
          <blockquote>
            "I come for the sound, I leave with a little more clarity and a lighter chest."<cite>— R., software designer</cite>
          </blockquote>
          <blockquote>
            "The cohort format made it easy to connect without pressure. The rhythm is gentle and precise."<cite>— M., artist</cite>
          </blockquote>
        </div>
      </div>
    </section>

    <section class="benefits reveal" data-reveal>
      <div class="wrap">
        <h2>Why join a cohort?</h2>
        <ul class="benefit-grid">
          <li>
            <h3>Shared container</h3>
            <p>Small groups create a predictable pace — people settle together more quickly than in an open format.</p>
          </li>
          <li>
            <h3>Layered sound design</h3>
            <p>Instruments, voice, and silence are composed to meet different nervous system states through the hour.</p>
          </li>
          <li>
            <h3>Take-home anchors</h3>
            <p>Simple practices and a short reflection at the end help sustain the effect for days.</p>
          </li>
        </ul>
      </div>
    </section>

    <section class="process reveal" data-reveal>
      <div class="wrap">
        <h2>What to expect</h2>
        <ol class="steps">
          <li><strong>Arrival:</strong> Soft seating, brief welcome, intention invite.</li>
          <li><strong>Settle:</strong> A short breath-led entry and gentle attunement.</li>
          <li><strong>Sound journey:</strong> 35–45 minutes of layered sound with pauses for presence.</li>
          <li><strong>Integration:</strong> Grounding and a chance to journal or share reflections.</li>
        </ol>
      </div>
    </section>

    <section class="faq reveal" data-reveal>
      <div class="wrap">
        <h2>Practical notes & safety</h2>
        <div class="qa">
          <div>
            <h3>What should I bring?</h3>
            <p>Comfortable layers, a mat or blanket, and anything that helps you feel supported. We provide bolsters and blankets on request.</p>
          </div>
          <div>
            <h3>Contraindications</h3>
            <p>Sound work is generally low-risk but may not suit people with certain conditions: recent traumatic brain injury, uncontrolled epilepsy, certain cardiac devices, or other medical concerns. If you have doubts, consult your healthcare provider and contact us at {{EMAIL}} before attending.</p>
          </div>
          <div>
            <h3>Accessibility</h3>
            <p>Our space is single-level and we strive to accommodate sensory and mobility needs. Email {{EMAIL}} with any access requests.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="cta reveal" data-reveal>
      <div class="wrap">
        <h2>Ready to reserve your spot?</h2>
        <p>Choose a cohort date or inquire about a private session for groups and workplaces.</p>
        <div class="cta-actions">
          <a class="btn primary" href="/book.html">Book a seat</a>
          <a class="btn ghost" href="/contact.html">Ask a question</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p>{{TAGLINE}}</p>
        </div>
        <div>
          <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <p>{{CITY}}, {{STATE}}</p>
        </div>
        <div>
          <nav>
            <a href="/events.html">Events</a>
            <a href="/pricing.html">Pricing</a>
            <a href="/about.html">About</a>
            <a href="/faq.html">FAQ</a>
          </nav>
        </div>
      </div>
      <small>All gatherings include a short screening for safety. Please review contraindications above.</small>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="exercise-modal" class="modal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="exercise-title">
    <div class="modal-panel">
      <button class="modal-close" id="modal-close" aria-label="Close">×</button>
      <h3 id="exercise-title">Quick Practice</h3>
      <p class="muted">Choose a short companion: breathe, write, or set an intention.</p>
      <div class="exercise-tabs">
        <button class="tab active" data-mode="breath">Breathing</button>
        <button class="tab" data-mode="journal">Journaling</button>
        <button class="tab" data-mode="intention">Intention</button>
      </div>
      <div class="exercise-body">
        <div class="mode" data-mode="breath">
          <div class="breath-visual" id="breath-visual" aria-hidden="true">
            <div class="circle" id="breath-circle"></div>
          </div>
          <p id="breath-instructions">Follow the pulse: inhale — hold — exhale.</p>
          <div class="breath-controls">
            <label>Duration: <select id="breath-duration"><option value="1">1 min</option><option value="2" selected>2 min</option><option value="3">3 min</option></select></label>
            <button class="btn" id="breath-start">Start</button>
            <button class="btn ghost" id="breath-stop">Stop</button>
          </div>
        </div>
        <div class="mode hidden" data-mode="journal">
          <p class="muted">A timed prompt to write quickly — 5 minutes suggested.</p>
          <textarea id="journal-text" placeholder="What would you like to leave, or bring forward?" rows="6"></textarea>
          <div class="journal-actions">
            <button class="btn" id="journal-start">Start 5-min timer</button>
            <button class="btn ghost" id="journal-clear">Clear</button>
          </div>
        </div>
        <div class="mode hidden" data-mode="intention">
          <p class="muted">A short invitation to create a single-word or sentence intention you can return to.</p>
          <input id="intention-input" placeholder="My intention is…" />
          <div class="intent-actions">
            <button class="btn" id="intention-save">Save</button>
            <button class="btn ghost" id="intention-dismiss">Close</button>
          </div>
          <p class="tiny">Saved intentions will remain in your browser until cleared.</p>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
