{"path":"assets/css/styles.css","content":"/* Earthy warm theme - no external fonts */
:root{
  --bg:#f6f2ec;
  --muted:#6b5a4c;
  --accent:#b8865b;
  --accent-2:#8a6a45;
  --card:#fff;
  --shadow:rgba(37,31,28,0.06);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;font-size:16px;color:var(--muted);background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:1100px;margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg,rgba(216,196,166,0.12),transparent);backdrop-filter:blur(2px)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none}
.main-nav a{margin:0 0.6rem;color:var(--muted);text-decoration:none}
.main-nav .cta{background:var(--accent);color:#fff;padding:0.5rem 0.9rem;border-radius:8px;text-decoration:none}
.try-btn{background:transparent;border:1px solid var(--accent);padding:.4rem .6rem;border-radius:8px;color:var(--accent);cursor:pointer}
.hero{padding:3.5rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:2rem;align-items:center}
.lead{font-size:1.05rem;color:#544438}
.hero-art svg{width:100%;height:auto}
.btn{display:inline-block;padding:0.6rem 1rem;border-radius:10px;border:1px solid transparent;background:var(--card);cursor:pointer;text-decoration:none;color:var(--muted)}
.btn.primary{background:var(--accent);color:#fff;border-color:var(--accent)}
.btn.ghost{background:transparent;border-color:var(--accent-2);color:var(--accent-2)}
.tiny{font-size:0.85rem;color:#7a6a5c}
.testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
blockquote{background:var(--card);padding:1rem;border-radius:10px;box-shadow:0 6px 18px var(--shadow);font-style:italic;color:#4a3d33}
cite{display:block;margin-top:.6rem;font-style:normal;color:#6d5949}
.benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;list-style:none;padding:0;margin:1rem 0}
.benefit-grid li{background:var(--card);padding:1rem;border-radius:12px;box-shadow:0 6px 18px var(--shadow)}
.steps{background:linear-gradient(180deg,rgba(188,160,131,0.06),transparent);padding:1rem;border-radius:10px}
.qa{display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem}
.qa h3{margin-top:0}
.cta{padding:3rem 0;text-align:center}
.cta .btn{margin:0 .5rem}
.site-footer{border-top:1px solid rgba(120,98,75,0.08);padding:2rem 0;background:transparent}
.foot-grid{display:flex;justify-content:space-between;gap:1rem}
.small{font-size:0.85rem}

/* Modal styles */
.modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(17,13,9,0.45);opacity:0;pointer-events:none;transition:opacity .25s ease}
.modal[aria-hidden="false"]{opacity:1;pointer-events:auto}
.modal-panel{background:var(--card);width:clamp(320px,80%,720px);padding:1.25rem;border-radius:12px;box-shadow:0 20px 40px rgba(24,18,14,0.2);position:relative}
.modal-close{position:absolute;right:12px;top:10px;border:0;background:transparent;font-size:1.5rem;cursor:pointer}
.exercise-tabs{display:flex;gap:.5rem;margin:0.5rem 0}
.exercise-tabs .tab{padding:.4rem .6rem;border-radius:8px;border:1px solid transparent;background:transparent;cursor:pointer}
.exercise-tabs .tab.active{background:var(--accent);color:#fff}
.mode{margin-top:0.6rem}
.hidden{display:none}
#journal-text{width:100%;padding:.6rem;border-radius:8px;border:1px solid #e4dbcf}
#intention-input{width:100%;padding:.6rem;border-radius:8px;border:1px solid #e4dbcf}

/* breathing visual */
.breath-visual{display:flex;align-items:center;justify-content:center;height:160px}
.circle{width:80px;height:80px;border-radius:50%;background:linear-gradient(180deg,var(--accent) 0%,var(--accent-2) 100%);box-shadow:0 10px 30px rgba(138,106,69,0.2);transform:scale(1)}
.pulse{animation:pulse 4s ease-in-out infinite}
@keyframes pulse{0%{transform:scale(.85)}40%{transform:scale(1.18)}60%{transform:scale(1.08)}100%{transform:scale(.9)}}

/* reveal animation */
.reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
.revealed{opacity:1;transform:none}

/* reduced motion */
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
  .pulse{animation:none}
}

/* responsive */
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .testimonials{grid-template-columns:1fr}
  .benefit-grid{grid-template-columns:1fr}
  .qa{grid-template-columns:1fr}
  .foot-grid{flex-direction:column}
}

/* pattern background */
body::before{content:"";position:fixed;inset:0;pointer-events:none;background-image:url('/assets/img/pattern.svg');opacity:0.06;mix-blend-mode:multiply}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // helper
  var $ = function(sel, ctx){ return (ctx||document).querySelector(sel); };
  var $$ = function(sel, ctx){ return Array.from((ctx||document).querySelectorAll(sel)); };

  // Modal logic
  var modal = $('#exercise-modal');
  var openBtns = [$('#try-now'), $('#try-now-2')];
  var closeBtn = $('#modal-close');
  var tabs = $$('.tab', modal);
  var modes = $$('.mode', modal);

  function openModal(){ modal.setAttribute('aria-hidden','false'); document.body.style.overflow = 'hidden'; }
  function closeModal(){ modal.setAttribute('aria-hidden','true'); document.body.style.overflow = ''; stopBreath(); }

  openBtns.forEach(function(b){ if(b) b.addEventListener('click', openModal); });
  closeBtn && closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){ if(e.target === modal) closeModal(); });

  // tabs
  tabs.forEach(function(t){ t.addEventListener('click', function(){ tabs.forEach(function(x){x.classList.remove('active')}); t.classList.add('active'); var mode = t.getAttribute('data-mode'); modes.forEach(function(m){ if(m.getAttribute('data-mode')===mode){ m.classList.remove('hidden'); } else { m.classList.add('hidden'); }}); }); });

  // Breathing exercise
  var breathStart = $('#breath-start');
  var breathStop = $('#breath-stop');
  var breathCircle = $('#breath-circle');
  var breathDurationSel = $('#breath-duration');
  var breathTimer = null;
  var breathPhase = 0; // 0 inhale, 1 hold, 2 exhale
  var breathRunning = false;

  function startBreath(){
    if(breathRunning) return;
    var minutes = Number(breathDurationSel.value) || 2;
    var total = minutes * 60 * 1000; // ms
    var cycle = 4000; // 4s per cycle (inhale+hold+exhale mixture)
    var cycles = Math.max(1, Math.floor(total / cycle));
    var count = 0;
    breathRunning = true;
    breathCircle.classList.add('pulse');
    breathTimer = setInterval(function(){
      count++;
      if(count>=cycles) stopBreath();
    }, cycle);
  }
  function stopBreath(){ breathRunning=false; clearInterval(breathTimer); breathTimer=null; breathCircle.classList.remove('pulse'); }
  breathStart && breathStart.addEventListener('click', startBreath);
  breathStop && breathStop.addEventListener('click', stopBreath);

  // Journaling simple timer
  var journalStart = $('#journal-start');
  var journalText = $('#journal-text');
  var journalTimer=null;
  journalStart && journalStart.addEventListener('click', function(){
    var seconds = 300; // 5 min
    var orig = journalStart.textContent;
    journalStart.disabled = true;
    journalTimer = setInterval(function(){
      seconds--;
      journalStart.textContent = 'Time left: ' + seconds + 's';
      if(seconds<=0){ clearInterval(journalTimer); journalTimer=null; journalStart.disabled=false; journalStart.textContent = orig; alert('Time is up — take a breath.'); }
    },1000);
  });
  var journalClear = $('#journal-clear'); journalClear && journalClear.addEventListener('click', function(){ journalText.value=''; });

  // Intention save
  var intentionInput = $('#intention-input');
  var intentionSave = $('#intention-save');
  var intentionDismiss = $('#intention-dismiss');
  intentionSave && intentionSave.addEventListener('click', function(){ if(!intentionInput.value) return alert('Write a short intention.'); localStorage.setItem('sound_intention', intentionInput.value); alert('Saved to your browser.'); });
  intentionDismiss && intentionDismiss.addEventListener('click', closeModal);

  // Persist saved intention to show if present
  var saved = localStorage.getItem('sound_intention'); if(saved && intentionInput) intentionInput.placeholder = saved;

  // Scroll-triggered reveal with reduced motion support
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var revealEls = document.querySelectorAll('[data-reveal]');
  if(prefersReduced){ revealEls.forEach(function(el){ el.classList.add('revealed'); }); }
  else if('IntersectionObserver' in window){
    var obs = new IntersectionObserver(function(entries){ entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('revealed'); obs.unobserve(e.target); } }); },{threshold:0.12});
    revealEls.forEach(function(el){ obs.observe(el); });
  } else { revealEls.forEach(function(el){ el.classList.add('revealed'); }); }

  // Basic keyboard accessibility for modal (escape)
  document.addEventListener('keydown', function(e){ if(e.key==='Escape' && modal.getAttribute('aria-hidden')==='false'){ closeModal(); } });

  // Small enhancement: focus trap basic
  modal.addEventListener('keydown', function(e){ if(e.key==='Tab'){ var focusable = Array.from(modal.querySelectorAll('button,a,input,textarea,select')).filter(function(n){ return n.offsetParent !== null; }); if(focusable.length){ var idx = focusable.indexOf(document.activeElement); if(e.shiftKey && idx===0){ focusable[focusable.length-1].focus(); e.preventDefault(); } else if(!e.shiftKey && idx===focusable.length-1){ focusable[0].focus(); e.preventDefault(); } } } });

  // init: ensure modal hidden
  modal.setAttribute('aria-hidden','true');
})();"} 
